INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(37211, 'Zephaniah 1:2', 'Zephaniah', 1, 2, '”زۀ به د زمکې د مخ نه هر يو څيز ختم کړم،“ مالِک خُدائ فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah1_verse_2.mp3', '', 1761754199, 1761754199),
(37212, 'Zephaniah 1:3', 'Zephaniah', 1, 3, '”زۀ به بنى آدم او ځناور دواړه ختم کړم، زۀ به د هوا مارغان او د سمندر کبان ختم کړم. د بدعملو د کاڼو بُتان به تباه کړم او انسان به د زمکې د مخ نه ختم کړم،“ مالِک خُدائ فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah1_verse_3.mp3', '', 1761754199, 1761754199),
(37213, 'Zephaniah 1:4', 'Zephaniah', 1, 4, '”زۀ به خپل لاس د يهوداه او د هغوئ ټولو خلاف وراوږد کړم څوک چې په يروشلم کښې اوسيږى. زۀ به د دې ځائ نه د بعل د عبادت يادونه، د بُت پرستانو نومونه او بُت پرسته اِمامان ختم کړم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah1_verse_4.mp3', '', 1761754199, 1761754199),
(37214, 'Zephaniah 1:5', 'Zephaniah', 1, 5, 'هغه څوک چې په چتونو د نمر، سپوږمۍ او ستورو عبادت کوى او هغوئ ته سجدې کوى، او په يو وخت کښې مالِک خُدائ ته سجدې کوى او د هغۀ په نوم قسم خورى او هم په هغه وخت کښې د مولک بُت په نوم قسم خورى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah1_verse_5.mp3', '', 1761754199, 1761754199),
(37215, 'Zephaniah 1:6', 'Zephaniah', 1, 6, 'او دا هم هغه خلق دى چا چې ما ته شا کړې ده او زما لټون نۀ کوى او نۀ زما لارښودنه غواړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah1_verse_6.mp3', '', 1761754199, 1761754199),
(37216, 'Zephaniah 1:7', 'Zephaniah', 1, 7, 'د مالِک خُدائ په وړاندې خاموشه اوسه، ځکه چې د مالِک خُدائ د قيامت ورځ نزدې ده. مالِک خُدائ يوه قربانى تياره کړې ده، هغۀ هغه څوک مقدس کړى دى چې هغۀ راغوښتى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah1_verse_7.mp3', '', 1761754199, 1761754199),
(37217, 'Zephaniah 1:8', 'Zephaniah', 1, 8, 'د مالِک خُدائ د قربانۍ په ورځ به زۀ شهزادګانو او د بادشاه زامنو له سزا ورکړم او هر هغه چا له چې د غېر قومونو جامې اچوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah1_verse_8.mp3', '', 1761754199, 1761754199),
(37218, 'Zephaniah 1:9', 'Zephaniah', 1, 9, 'په هغه ورځ به زۀ هغوئ ټولو له سزا ورکړم څوک چې د بُت د عزت دپاره په درشل وردانګى، د خپلو مالِکانو کورونه د ظلم او ټګۍ نه ډکوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah1_verse_9.mp3', '', 1761754199, 1761754199),
(37219, 'Zephaniah 1:10', 'Zephaniah', 1, 10, 'په هغه ورځ،“ مالِک خُدائ فرمائى، ”يوه چغه به د کب دروازې نه اوچته شى، د ښار د نوې حصې نه به ماتم، او د غونډو نه به د ماتېدو آوازونه راځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah1_verse_10.mp3', '', 1761754199, 1761754199),
(37220, 'Zephaniah 1:11', 'Zephaniah', 1, 11, 'د غم فرياد وکړئ، تاسو ټول چې په نوې ښار کښې اوسېږئ، ستاسو ټول سوداګر به جارُو شى، هغه ټول چې د سپينو زرو روزګار کوى هغه به تباه شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah1_verse_11.mp3', '', 1761754199, 1761754199),
(37221, 'Zephaniah 1:12', 'Zephaniah', 1, 12, 'زۀ به ډيوه په لاس ګوټ په ګوټ په يروشلم کښې وګرځم. زۀ به هغه خلقو له سزا ورکړم چې په خپل ځان مطمئن دى، هغه څوک چې دا سوچ کوى چې مالِک خُدائ به مونږ سره نۀ ښۀ کوى او نۀ بد.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah1_verse_12.mp3', '', 1761754199, 1761754199),
(37222, 'Zephaniah 1:13', 'Zephaniah', 1, 13, 'د هغوئ مال دولت به لوټ شى او د هغوئ کورونه به وران شى. هغوئ به کورونه جوړوى خو په کښې به نۀ اوسيږى، هغوئ به د انګورو باغونه وکَرى خو مے به ترې ونۀ څښى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah1_verse_13.mp3', '', 1761754199, 1761754199),
(37223, 'Zephaniah 1:14', 'Zephaniah', 1, 14, 'د مالِک خُدائ د قيامت لويه ورځ رانزدې ده، ډېره نزدې ده او زر راتلونکى ده. غوږ شئ، د مالِک خُدائ د ورځ ژړا به سخته وى، په هغه ورځ به ښۀ تکړه فوجيان هم چغې وهى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah1_verse_14.mp3', '', 1761754199, 1761754199),
(37224, 'Zephaniah 1:15', 'Zephaniah', 1, 15, 'هغه به د غضب ورځ وى، د غم او مصيبت ورځ به وى، د تباهۍ او بربادۍ ورځ به وى، د تورې تيارې او خړې ورځ به وى او د تکې تورې وريځې ورځ به وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah1_verse_15.mp3', '', 1761754199, 1761754199),
(37225, 'Zephaniah 1:16', 'Zephaniah', 1, 16, 'د بيګل غږولو او د جنګى نعرو ورځ چې د مضبوطو ښارونو خلاف او د لوړو برجونو خلاف به وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah1_verse_16.mp3', '', 1761754199, 1761754199),
(37226, 'Zephaniah 1:17', 'Zephaniah', 1, 17, 'زۀ به په خلقو داسې مصيبتونه راولم چې هغوئ به د ړندو په شان ګرځى. ځکه چې هغوئ زما خلاف ګناه کړې ده. د هغوئ وينه به د خاورو په شان تويه شى او د هغوئ لاشونه به سخا شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah1_verse_17.mp3', '', 1761754199, 1761754199),
(37227, 'Zephaniah 1:18', 'Zephaniah', 1, 18, 'د مالِک خُدائ د غضب په ورځ به نۀ د هغوئ سپين زر او نۀ به د هغوئ سرۀ زر هغوئ ته خلاصون ورکولے شى. د هغۀ د غېرت په اور به ټوله دُنيا وسوزيږى ځکه چې هغه به ناګهانه د هغوئ ټولو خاتمه راولى څوک چې د زمکې په مخ باندې اوسيږى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah1_verse_18.mp3', '', 1761754199, 1761754199),
(37228, 'Jeremiah 34:1', 'Jeremiah', 34, 1, 'کله چې د بابل بادشاه نبوکدنضر او د هغۀ ټولو لښکرو او د هغۀ د بادشاهت د لاندې ټولو مُلکونو چې په يروشلم او د هغۀ په خوا او شا ښارونو باندې حمله کوله نو د مالِک خُدائ پېغام يرمياه ته ورکړے شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah34_verse_1.mp3', '', 1761754199, 1761754199),
(37229, 'Jeremiah 34:2', 'Jeremiah', 34, 2, 'مالِک خُدائ د بنى اِسرائيلو خُدائ پاک يرمياه ته وفرمائيل چې، ”لاړ شه او د يهوداه بادشاه صدقياه ته ووايه چې، مالِک خُدائ فرمائى چې زۀ دا ښار د بابل بادشاه ته حواله کړم، او هغه به اوس دې ښار ته اور واچوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah34_verse_2.mp3', '', 1761754199, 1761754199),
(37230, 'Jeremiah 34:3', 'Jeremiah', 34, 3, 'تۀ به د هغۀ د ګرفتارى نه ونۀ تښتې بلکې په يقين سره به تۀ ګرفتار شې او هغۀ ته به حواله کړے شې. تۀ به د بابل بادشاه په خپلو سترګو ووينې، او هغه به تا سره مخامخ خبرې وکړى. او هغه به تا بابل ته جلاوطن کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah34_verse_3.mp3', '', 1761754199, 1761754199),
(37231, 'Jeremiah 34:4', 'Jeremiah', 34, 4, 'نو بيا اے صدقياه د يهوداه بادشاه، ما ته غوږ شه. مالِک خُدائ ستا په حقله فرمائى چې، تۀ به په جنګ کښې قتل نۀ شې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah34_verse_4.mp3', '', 1761754199, 1761754199),
(37232, 'Jeremiah 34:5', 'Jeremiah', 34, 5, 'بلکې تۀ به په خپل عام مرګ باندې مړ شې. څنګه چې خلقو ستا د پلار نيکۀ د جنازې د عزت دپاره خوشبو سوزوله څوک چې ستا نه وړاندې بادشاهان وُو، نو دغه شان به خلق ستا د جنازې د عزت دپاره خوشبو وسوزوى. او هغوئ به ماتم کوى او وائى به چې، افسوس، اے زمونږه بادشاه، تۀ مړ شوې. دا د مالِک خُدائ فرمان دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah34_verse_5.mp3', '', 1761754199, 1761754199),
(37233, 'Jeremiah 34:6', 'Jeremiah', 34, 6, 'نو بيا يرمياه پېغمبر دا پېغام د يهوداه بادشاه صدقياه ته په يروشلم کښې ورکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah34_verse_6.mp3', '', 1761754199, 1761754199),
(37234, 'Jeremiah 34:7', 'Jeremiah', 34, 7, 'په هغه وخت کښې د بابل بادشاه لښکرو د يروشلم او د يهوداه د نورو ښارونو په خلاف جنګ کولو کوم چې لکيس او عزيقه وُو. صرف دا مضبوط ښارونه وُو چې د قبضې نه پاتې شوى وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah34_verse_7.mp3', '', 1761754199, 1761754199),
(37235, 'Jeremiah 34:8', 'Jeremiah', 34, 8, 'د مالِک خُدائ دا پېغام يرمياه ته ورکړے شو پس د دې نه چې صدقياه بادشاه او د يروشلم ټولو خلقو د غلامانو د آزادولو دپاره لوظ وکړو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah34_verse_8.mp3', '', 1761754199, 1761754199),
(37236, 'Jeremiah 34:9', 'Jeremiah', 34, 9, 'او ټولو په دې اتفاق وکړو چې هر څوک به خپل عبرانى غلامان او وينځې آزادوى، او هيڅ څوک به خپل د مُلک سړے يا ښځه بند نۀ ساتى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah34_verse_9.mp3', '', 1761754199, 1761754199),
(37237, 'Jeremiah 34:10', 'Jeremiah', 34, 10, 'ټولو مشرانو او خلقو چا چې هم دا لوظ کړے وو هغوئ دا خبره ومنله چې هغوئ به خپل غلامان او وينځې آزادوى او نور به هغوئ په خپله قبضه کښې نۀ ساتى او هغوئ يې آزاد کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah34_verse_10.mp3', '', 1761754199, 1761754199),
(37238, 'Jeremiah 34:11', 'Jeremiah', 34, 11, 'خو وروستو هغوئ خپله فېصله بدله کړه، هغوئ آزاد شوى غلامان واپس راوستل او هغوئ يې بيا په زور سره دوباره خپل غلامان او وينځې جوړ کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah34_verse_11.mp3', '', 1761754199, 1761754199),
(37239, 'Jeremiah 34:12', 'Jeremiah', 34, 12, 'نو بيا د مالِک خُدائ کلام په يرمياه نازل شو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah34_verse_12.mp3', '', 1761754199, 1761754199),
(37240, 'Jeremiah 34:13', 'Jeremiah', 34, 13, '”ما ستاسو د پلار نيکۀ سره لوظ وکړو کله چې ما هغوئ د مِصر نه د غلامۍ د مُلک نه رابهر او آزاد کړل. نو ما وفرمائيل چې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah34_verse_13.mp3', '', 1761754199, 1761754199),
(37241, 'Jeremiah 34:14', 'Jeremiah', 34, 14, 'په هر يو اوؤم کال تاسو هر هغه عبرانى چې خپل ځان يې په تاسو خرڅ کړے دے آزاد کړئ. د شپږ کاله د خِدمت کولو نه وروستو، نو په کار دے چې تاسو هغه آزاد کړئ او رُخصت يې کړئ. خو ستاسو پلار نيکۀ زما خبرو ته نۀ غوږ ونيولو او نۀ يې ورته توجو ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah34_verse_14.mp3', '', 1761754199, 1761754199),
(37242, 'Jeremiah 34:15', 'Jeremiah', 34, 15, 'خو اوس تاسو پښېمانه شوئ او توبه مو وويستله او خپله فېصله مو بدله کړه او هغه کار مو وکړو چې څۀ زما په نظر کښې صحيح وو، او تاسو هر يو د خپلو غلامانو د آزادولو اعلان وکړو. او دا چې تاسو زما په کور کښې چې زما د نوم مهر پرې لګولے شوے دے ما سره لوظ وکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah34_verse_15.mp3', '', 1761754199, 1761754199),
(37243, 'Jeremiah 34:16', 'Jeremiah', 34, 16, 'خو تاسو بيا خپله فېصله بدله کړه او زما د نوم بې‌حرمتى مو وکړه، او تاسو بيا هر يو سړے غلام او ښځه مو واپس وينځه کړه څوک چې تاسو آزاد کړى وُو. نو بيا تاسو هغوئ په زور سره دوباره غلامان او وينځې کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah34_verse_16.mp3', '', 1761754199, 1761754199),
(37244, 'Jeremiah 34:17', 'Jeremiah', 34, 17, 'نو ځکه مالِک خُدائ فرمائى چې، تاسو زما پيروى ونۀ کړه، تاسو د خپل مُلک خلقو ته د آزادۍ اعلان ونۀ کړو. نو زۀ اوس بيا تاسو ته دغه شان د آزادۍ اعلان کوم. مالِک خُدائ فرمائى چې ستاسو آزادى به داسې وى چې زۀ به تاسو په تُورې، وبا او قحط باندې مړۀ کړم. زۀ به تاسو ټولې دُنيا ته د عبرت او د يرې سبب وګرځوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah34_verse_17.mp3', '', 1761754199, 1761754199),
(37245, 'Jeremiah 34:18', 'Jeremiah', 34, 18, 'ځکه چې تاسو ما سره د لوظ شرائط مات کړل نو زۀ به تاسو هم دوه ځايه کړم لکه څنګه چې تاسو سخى دوه ځايه کړى وُو او د هغې په مينځ کښې تېر شوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah34_verse_18.mp3', '', 1761754199, 1761754199),
(37246, 'Jeremiah 34:19', 'Jeremiah', 34, 19, 'آو، زۀ به تاسو په مينځ وشلوم، هغه کۀ تاسو د يهوداه او يروشلم آفسران، د دربار خصيان آفسران، اِمامان او يا عام خلق هم يئ، ځکه چې تاسو ما سره خپل لوظ مات کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah34_verse_19.mp3', '', 1761754199, 1761754199),
(37247, 'Jeremiah 34:20', 'Jeremiah', 34, 20, 'نو زۀ به مو خپلو دشمنانو ته حواله کړم څوک چې ستاسو مرګ پسې ګرځى. ستاسو د مړو لاشونه به د هوا د مارغانو او د ګيدړانو خوراک کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah34_verse_20.mp3', '', 1761754199, 1761754199),
(37248, 'Jeremiah 34:21', 'Jeremiah', 34, 21, 'زۀ به د يهوداه بادشاه صدقياه او د هغۀ آفسران هم د هغوئ دشمنانو ته حواله کړم څوک چې د هغوئ مرګ پسې ګرځى. کۀ څۀ هم چې د بابليانو د بادشاه لښکرو خپلې حملې ستاسو خلاف بندى کړى دى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah34_verse_21.mp3', '', 1761754199, 1761754199),
(37249, 'Jeremiah 34:22', 'Jeremiah', 34, 22, 'مالِک خُدائ فرمائى چې، زۀ به هغوئ ته حُکم ورکړم او بيا به زۀ هغوئ واپس دې ښار ته راولم. هغوئ به ستاسو خلاف جنګ وکړى او هغوئ به دا ښار قبضه کړى او وبه يې سوزوى. او زۀ به د يهوداه ښارونه وران او تباه کړم نو بيا به څوک هم هلته نۀ اوسيږى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah34_verse_22.mp3', '', 1761754199, 1761754199),
(37250, 'Judges 21:1', 'Judges', 21, 1, 'په هغه وخت کې چې اسراییلیان په مصفه کې سره راټول شوي وو، هغوی داسې قسم خوړلی ؤ: «زمونږ څخه به هېڅوک خپله لور بنیامینیانو ته په نکاح نه ورکوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges21_verse_1.mp3', '', 1761754199, 1761754199),
(37251, 'Judges 21:2', 'Judges', 21, 2, 'نو د اسراییلو قوم بیت ییل ته لاړ او هلته تر ماښامه پورې د خدای په حضور کې کښېناستل. هغوی په لوړ اواز سره سخت وژړل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges21_verse_2.mp3', '', 1761754199, 1761754199),
(37252, 'Judges 21:3', 'Judges', 21, 3, 'او ویې ویل: «ای د اسراییلو څښتن خدایه، د اسراییلو سره ولې داسې وشول؟ د بنیامین قبیله ولې د اسراییلو د منځ څخه ورکه شي؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges21_verse_3.mp3', '', 1761754199, 1761754199),
(37253, 'Judges 21:4', 'Judges', 21, 4, 'بله ورځ سهار وختي خلکو د قربانۍ ځای جوړ کړ او سوځېدونکې او د سلامتۍ نذرانې یې وړاندې کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges21_verse_4.mp3', '', 1761754199, 1761754199),
(37254, 'Judges 21:5', 'Judges', 21, 5, 'بیا هغوی د یو بل څخه پوښتنه وکړه: «د اسراییلو د ټولو قبیلو څخه داسې کومه ډله شته چې د مصفې په غونډه کې د څښتن په حضور کې نه وه حاضره شوې؟» هغوی په کلکه دا قسم خوړلی ؤ چې هرڅوک چې په مصفه کې د څښتن په حضور کې حاضر نه شي، هغه دې ووژل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges21_verse_5.mp3', '', 1761754199, 1761754199),
(37255, 'Judges 21:6', 'Judges', 21, 6, 'نو د اسراییلو خلکو د خپلو بنیامیني ورونو دپاره افسوس کاوه او ویل به یې: «نن اسراییلو د خپلو قبیلو څخه یوه قبیله له لاسه ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges21_verse_6.mp3', '', 1761754199, 1761754199),
(37256, 'Judges 21:7', 'Judges', 21, 7, 'اوس د هغو بنیامینیانو دپاره چې ژوندي پاتې شوي دي، څه وکړو چې د هغوی دپاره ښځې پیدا کړو؟ ځکه چې مونږ د څښتن په نوم قسم خوړلی دی چې خپلې لورګانې به هغوی ته نه ورکوو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges21_verse_7.mp3', '', 1761754199, 1761754199),
(37257, 'Judges 21:8', 'Judges', 21, 8, 'کله چې هغوی پوښتنه وکړه: «ایا د اسراییلو د قبیلو څخه کومه ډله د مصفې په غونډه کې حاضره شوې نه وه؟» هغوی ته معلومه شوه چې د یابیش څخه چې په جلعاد کې دی هېڅوک نه ؤ راغلی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges21_verse_8.mp3', '', 1761754199, 1761754199),
(37258, 'Judges 21:9', 'Judges', 21, 9, 'ځکه کله چې هغوی خلک وشمېرل، نو ورته معلومه شوه چې د یابیش جلعاد څخه هېڅوک هلته نه ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges21_verse_9.mp3', '', 1761754199, 1761754199),
(37259, 'Judges 21:10', 'Judges', 21, 10, 'نو غونډې خپل دولس زره زړور کسان ولېږل او هغوی ته یې دا امر ورکړ: «لاړ شئ او د یابیش ټول خلک د ښځو او ماشومانو سره ووژنئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges21_verse_10.mp3', '', 1761754199, 1761754199),
(37260, 'Judges 21:11', 'Judges', 21, 11, 'ټول نارینه او همدارنګه هغه ټولې ښځې چې پېغلې نه وي، ووژنئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges21_verse_11.mp3', '', 1761754199, 1761754199),
(37261, 'Judges 21:12', 'Judges', 21, 12, 'هغوی د جلعاد په یابیش باندې حمله وکړه او د څلور سوه پېغلو سره چې هلته یې پیدا کړې وې د شیلوه کمپ ته چې د کنعان په خاوره کې ؤ، راستانه شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges21_verse_12.mp3', '', 1761754199, 1761754199),
(37262, 'Judges 21:13', 'Judges', 21, 13, 'بیا ټولې غونډې هغو پاتې بنیامینیانو ته چې د رمون د ګټ سره اوسېدل، یو پیغام ولېږه او هغوی ته یې د سولې وړاندیز وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges21_verse_13.mp3', '', 1761754199, 1761754199),
(37263, 'Judges 21:14', 'Judges', 21, 14, 'نو بنیامینیان بېرته راغلل او اسراییلیانو هغوی ته د یابیش هغه نجونې چې ژوندۍ پاتې شوې وې، ورکړې. خو دا نجونې د هغوی ټولو دپاره بس نه وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges21_verse_14.mp3', '', 1761754199, 1761754199),
(37264, 'Judges 21:15', 'Judges', 21, 15, 'د اسراییلو خلک په بنیامینیانو باندې ډېر خفه وو، ځکه چې څښتن د هغوی د قبیلو ترمنځ بې اتفاقي پیدا کړې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges21_verse_15.mp3', '', 1761754199, 1761754199),
(37265, 'Judges 21:16', 'Judges', 21, 16, 'نو د غونډې مشرانو وویل: «د بنیامین د قبیلې ټولې ښځې وژل شوې دي. نو څه باید وکړو چې د هغوی پاتې سړیو ته ښځې پیدا کړو؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges21_verse_16.mp3', '', 1761754199, 1761754199),
(37266, 'Judges 21:17', 'Judges', 21, 17, 'پاتې ژوندي بنیامینیان باید وارثان ولري، ترڅو د اسراییلو یوه قبیله د تل دپاره له منځه لاړه نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges21_verse_17.mp3', '', 1761754199, 1761754199),
(37267, 'Judges 21:18', 'Judges', 21, 18, 'مونږ نه شو کولای چې خپلې لورګانې هغوی ته ورکړو، ځکه چې مونږ قسم خوړلی دی چې هرڅوک چې بنیامینیانو ته لور ورکړي په هغه باندې دې لعنت وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges21_verse_18.mp3', '', 1761754199, 1761754199),
(37268, 'Judges 21:19', 'Judges', 21, 19, 'بیا هغوی دا فکر وکړ چې په شیلوه کې د څښتن دپاره کلنی جشن نیول کیږي. (شیلوه د بیت ییل په شمال او د لبونه په جنوب کې او د هغې لارې په ختیځ کې ده چې د شکیم او بیت ییل ترمنځ ده.)', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges21_verse_19.mp3', '', 1761754199, 1761754199),
(37269, 'Judges 21:20', 'Judges', 21, 20, 'هغوی بنیامینیانو ته وویل: «لاړ شئ او د انګورو په باغونو کې پټ شئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges21_verse_20.mp3', '', 1761754199, 1761754199),
(37270, 'Judges 21:21', 'Judges', 21, 21, 'او هلته انتظار وباسئ. کله چې د شیلوه انجونې د جشن په دوران کې د نڅا دپاره دباندې راووځي، تاسو د انګورو د باغونو څخه راووځئ او د هغو څخه هر یو خپلو ځانونو ته یوه یوه انجلۍ په زور راونیسئ او د ځان سره یې د بنیامین خاورې ته بوځئ چې ستاسو ښځې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges21_verse_21.mp3', '', 1761754199, 1761754199),
(37271, 'Judges 21:22', 'Judges', 21, 22, 'که چېرې د هغوی پلرونه او ورونه تاسو ته راشي او اعتراض وکړي، نو تاسو کولای شئ چې هغوی ته داسې ووایئ: ‹مهرباني وکړئ مونږ ته اجازه راکړئ چې هغوی وساتو، ځکه چې مونږ هغوی د جنګ په دوران کې ستاسو څخه نه دي نیولې چې زمونږ ښځې شي. څرنګه چې تاسو هغوی مونږ ته نه دي راکړې، نو تاسو د خپل قسم په ماتولو ګناهکار نه یئ.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges21_verse_22.mp3', '', 1761754199, 1761754199),
(37272, 'Judges 21:23', 'Judges', 21, 23, 'بنیامینیانو همداسې وکړل. هغوی هر یو د هغو نجونو څخه چې په شیلوه کې یې نڅا کوله، یوه یوه انجلۍ د خپل ځان دپاره راونیوله او هغوی یې خپلې سیمې ته بوتللې. بیا هغوی خپل ښارګوټي بېرته اباد کړل او هلته اوسېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges21_verse_23.mp3', '', 1761754199, 1761754199),
(37273, 'Judges 21:24', 'Judges', 21, 24, 'نو اسراییلیان هم هر یو بېرته خپلې قبیلې، خپلې کورنۍ او خپلې ځمکې ته لاړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges21_verse_24.mp3', '', 1761754199, 1761754199),
(37274, 'Judges 21:25', 'Judges', 21, 25, 'په هغه زمانه کې اسراییلو پاچا نه درلود، نو هرچا به هغه کارونه کول چې زړه یې غوښتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges21_verse_25.mp3', '', 1761754199, 1761754199),
(37275, 'Judges 16:1', 'Judges', 16, 1, 'یوه ورځ شمشون د فلسطینیانو ښار غزې ته لاړ او هلته هغه یوه بدلمنه ښځه ولیدله او د هغې کور ته ورغی چې شپه ورسره تېره کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges16_verse_1.mp3', '', 1761754199, 1761754199),
(37276, 'Judges 16:2', 'Judges', 16, 2, 'د غزې خلک خبر شول چې شمشون هلته دی. نو هغوی هغه ځای کلابند کړ او هغه ته یې ټوله شپه د ښار په دروازه کې انتظار وکړ. هغوی ټوله شپه غلي وو او د ځانونو سره یې ویل: «مونږ به د سهار تر رڼا کېدلو پورې صبر وکړو او بیا به یې ووژنو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges16_verse_2.mp3', '', 1761754199, 1761754199),
(37277, 'Judges 16:3', 'Judges', 16, 3, 'خو شمشون تر نیمې شپې پورې هلته په بستره کې پروت ؤ. بیا هغه پاڅېده او د ښار دروازه یې د هغې د چوکاټ سره راونیوله او د اړم او ټولو شیانو سره یې وویستله. هغه یې په خپلو اوږو باندې کېښودله او د هغې غونډۍ سرته یې چې حبرون ته مخامخ وه، یووړله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges16_verse_3.mp3', '', 1761754199, 1761754199),
(37278, 'Judges 16:4', 'Judges', 16, 4, 'څه موده وروسته، شمشون په یوې انجلۍ باندې چې دلیله نومېدله او د سورق په دره کې اوسېدله، مین شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges16_verse_4.mp3', '', 1761754199, 1761754199),
(37279, 'Judges 16:5', 'Judges', 16, 5, 'د فلسطینیانو مشران هغې ته ورغلل او ورته ویې ویل: «شمشون وغولوه چې تاته ووایي چې هغه ولې دومره قوي دی. همدارنګه مونږ څنګه وکولای شو هغه مغلوب کړو، ترڅو هغه وتړو او کمزوری یې کړو. که دا کار وکړې، نو مونږ هر یو به تاته یوولس سوه د سپینو زرو سکې درکړو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges16_verse_5.mp3', '', 1761754199, 1761754199),
(37280, 'Judges 16:6', 'Judges', 16, 6, 'نو دلیلې شمشون ته وویل: «مهرباني وکړه ماته ووایه چې ته ولې دومره قوي یې. څنګه څوک کولای شي چې تا وتړي او کمزوری دې کړي؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges16_verse_6.mp3', '', 1761754199, 1761754199),
(37281, 'Judges 16:7', 'Judges', 16, 7, 'شمشون په ځواب کې وویل: «که چېرې څوک ما د لیندې په اوو نویو مزو باندې چې وچ شوي نه وي وتړي، نو زه به کمزوری شم او د عادي خلکو په شان به شم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges16_verse_7.mp3', '', 1761754199, 1761754199),
(37282, 'Judges 16:8', 'Judges', 16, 8, 'نو فلسطیني مشرانو دلیلې ته د کمان اووه نوي مزي چې وچ شوي نه وو، راوړل او هغې شمشون وتاړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges16_verse_8.mp3', '', 1761754199, 1761754199),
(37283, 'Judges 16:9', 'Judges', 16, 9, 'دلیلې یو څو کسان د خپل کور په بله کوټه کې پټ کړي وو، نو هغې شمشون ته غږ وکړ: «شمشونه، فلسطینیان راغلي دي چې تا ونیسي!» خو شمشون هغه مزي لکه د تار په شان چې په اور کې سوځېدلی وي، وشکول. نو هغوی د شمشون د زور په راز پوه نه شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges16_verse_9.mp3', '', 1761754199, 1761754199),
(37284, 'Judges 16:10', 'Judges', 16, 10, 'بیا دلیلې شمشون ته وویل: «تا په ما باندې ملنډې ووهلې او دروغ دې راته وویل. اوس ماته ووایه چې تا څنګه څوک تړلی شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges16_verse_10.mp3', '', 1761754199, 1761754199),
(37285, 'Judges 16:11', 'Judges', 16, 11, 'هغه وویل: «که چېرې څوک ما په داسې رسیو باندې وتړي چې هېڅ کار ورڅخه اخیستل شوی نه وي، نو زه به کمزوری شم او د عادي خلکو په شان به شم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges16_verse_11.mp3', '', 1761754199, 1761754199),
(37286, 'Judges 16:12', 'Judges', 16, 12, 'نو دلیلې نوې رسۍ راواخیستې او شمشون یې ورباندې وتاړه. د مخکې ځل په شان فلسطینیان په بله کوټه کې پټ وو. هغې شمشون ته غږ وکړ: «شمشونه، فلسطینیان راغلي دي چې تا ونیسي!» خو هغه د خپلو لاسونو څخه رسۍ لکه د تارونو په شان وشکولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges16_verse_12.mp3', '', 1761754199, 1761754199),
(37287, 'Judges 16:13', 'Judges', 16, 13, 'بیا دلیلې شمشون ته وویل: «ته تر اوسه پورې په ما باندې ملنډې وهې او ماته دروغ وایې. اوس راته ووایه چې تا څنګه څوک تړلی شي.» هغه په ځواب کې وویل: «که چېرې ته زما د سر اووه کوڅۍ په کارګاه باندې د تار سره واوبې او په یو مېخ باندې یې کلکې کړې، نو زه به د نورو خلکو په شان کمزوری شم.» نو په هغه وخت کې چې هغه ویده ؤ، دلیلې د هغه د سر اووه کوڅۍ له تار سره واوبدلې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges16_verse_13.mp3', '', 1761754199, 1761754199),
(37288, 'Judges 16:14', 'Judges', 16, 14, 'او په مېخ باندې یې کلکې کړې. هغې بیا شمشون ته غږ وکړ: «شمشونه، فلسطینیان راغلي دي چې تا ونیسي!» هغه د خوب څخه راویښ شو او کارګاه یې د مېخ او تارونو سره راوویستله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges16_verse_14.mp3', '', 1761754199, 1761754199),
(37289, 'Judges 16:15', 'Judges', 16, 15, 'نو دلیلې هغه ته وویل: «ته څنګه وایې چې زه درباندې ګرانه یم، حال دا چې ته په ما باندې باور هم نه کوې؟ دا درېم ځل دی چې ته په ما باندې ملنډې وهې او د خپل زور راز دې ماته نه وایې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges16_verse_15.mp3', '', 1761754199, 1761754199),
(37290, 'Judges 16:16', 'Judges', 16, 16, 'دلیلې په دې خبرو باندې چې هره ورځ به یې شمشون ته کولې، هغه ډېر تنګ کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges16_verse_16.mp3', '', 1761754199, 1761754199),
(37291, 'Judges 16:17', 'Judges', 16, 17, 'نو شمشون اخر هغې ته خپل راز ووایه. هغه وویل: «زما د سر ویښتان هېڅکله خریل شوي نه دي، ځکه چې زه د زېږېدلو د وخت څخه خدای ته د نذر په توګه وقف شوی یم. که چېرې زما سر وخریل شي، نو زه به خپل قوت له لاسه ورکړم او د نورو خلکو په شان به کمزوری شم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges16_verse_17.mp3', '', 1761754199, 1761754199),
(37292, 'Judges 16:18', 'Judges', 16, 18, 'کله چې دلیله پوه شوه چې شمشون ورته حقیقت بیان کړ، نو هغې د فلسطینیانو مشرانو ته دا خبر ورولېږه: «تاسو یوځل بیا راشئ شمشون ماته خپل راز بیان کړ.» نو هغوی راغلل او هغه پیسې چې د هغې سره یې وعده کړې وه، د ځان سره راوړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges16_verse_18.mp3', '', 1761754199, 1761754199),
(37293, 'Judges 16:19', 'Judges', 16, 19, 'دلیلې شمشون په خپل زنګون باندې ویده کړ، بیا هغې یو سړی راوغوښت او د شمشون د ویښتو اووه کوڅۍ یې وخریلې. نو دلیلې هغه کمزوری کړ او هغه خپل قوت له لاسه ورکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges16_verse_19.mp3', '', 1761754199, 1761754199),
(37294, 'Judges 16:20', 'Judges', 16, 20, 'بیا هغې شمشون ته غږ وکړ: «شمشونه، فلسطینیان راغلي دي چې تا ونیسي!» هغه له خوبه راویښ شو او فکر یې وکړ چې زه به د مخکې په شان په یو ټکان سره خپل ځان ازاد کړم. خو شمشون نه پوهېده چې څښتن هغه پریښی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges16_verse_20.mp3', '', 1761754199, 1761754199),
(37295, 'Judges 16:21', 'Judges', 16, 21, 'فلسطینیانو هغه ونیوه، سترګې یې ورڅخه وویستلې او غزې ته یې یووړ. هلته هغوی شمشون په برنجي زولنو وتاړه، په زندان کې یې واچاوه او مجبور یې کړ چې غلې دانې مېچن کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges16_verse_21.mp3', '', 1761754199, 1761754199),
(37296, 'Judges 16:22', 'Judges', 16, 22, 'خو د خریلو څخه وروسته د هغه ویښتانو بیا په راشنه کېدلو پیل وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges16_verse_22.mp3', '', 1761754199, 1761754199),
(37297, 'Judges 16:23', 'Judges', 16, 23, 'د فلسطینیانو مشران سره راټول شول چې جشن ونیسي او خپل خدای داجون ته یوه لویه قرباني وړاندې کړي. هغوی وویل: «زمونږ خدای مونږ ته په خپل دښمن شمشون باندې بری راکړی دی!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges16_verse_23.mp3', '', 1761754199, 1761754199),
(37298, 'Judges 16:26', 'Judges', 16, 26, 'شمشون هغه هلک ته چې دی یې له لاسه نیولی ؤ وویل: «ما پرېږده چې په هغو ستنو باندې لاس کېږدم چې دغه ودانۍ ورباندې ولاړه ده. زه غواړم چې تکیه ورباندې وکړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges16_verse_26.mp3', '', 1761754199, 1761754199),
(37299, 'Judges 16:27', 'Judges', 16, 27, 'هغه عبادتځای د سړیو او ښځو څخه ډک ؤ. د فلسطینیانو ټول مشران هلته موجود وو او په بام باندې نژدې درې زره سړي او ښځې وې چې شمشون ته یې کتل چې د هغوی دپاره یې ساعت تېري کوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges16_verse_27.mp3', '', 1761754199, 1761754199),
(37300, 'Judges 16:28', 'Judges', 16, 28, 'بیا شمشون څښتن ته دعا وکړه: «ای څښتن تعالی، ما در په یاد کړه. ای خدایه یوازې یوځل بیا ماته قوت راکړه چې د فلسطینیانو څخه د خپلو سترګو بدل واخلم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges16_verse_28.mp3', '', 1761754199, 1761754199),
(37301, 'Judges 16:29', 'Judges', 16, 29, 'نو شمشون هغه دوه منځنۍ ستنې چې ودانۍ ورباندې ولاړه وه ونیولې، یو لاس یې په یوې او بل لاس یې په بلې ستنې باندې کېښود. ستنې یې ټېل وهلې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges16_verse_29.mp3', '', 1761754199, 1761754199),
(37302, 'Judges 16:30', 'Judges', 16, 30, 'او چیغې یې کړې: «پرېږده چې د فلسطینیانو سره یو ځای مړ شم!» هغه په خپل ټول قوت سره ستنې ټېل وهلې او هغه ودانۍ په ټولو مشرانو او نورو خلکو باندې چې په هغه ځای کې وو، راولوېدله. نو په دې ډول د هغو خلکو شمېر چې شمشون د خپل مرګ په وخت کې ووژل د هغو خلکو څخه زیات ؤ چې هغه په خپل ټول ژوندانه کې وژلي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges16_verse_30.mp3', '', 1761754199, 1761754199),
(37303, 'Judges 16:31', 'Judges', 16, 31, 'د هغه ورونه او پاتې کورنۍ راغله چې د هغه مړی یوسي. هغوی د شمشون مړی بېرته یووړ او د خپل پلار مانوح په هدیره کې یې چې د زرعه او اشتاول ترمنځ پرته وه، ښخ کړ. شمشون شل کاله د اسراییلو مشر ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges16_verse_31.mp3', '', 1761754199, 1761754199),
(37304, 'Genesis 34:1', 'Genesis', 34, 1, 'یوه ورځ د یعقوب او لیه لور دینه د ځینو کنعاني ښځو د لیدلو دپاره لاړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis34_verse_1.mp3', '', 1761754199, 1761754199),
(37305, 'Genesis 34:2', 'Genesis', 34, 2, 'حمور حوي د هغې سیمې مشر ؤ. د هغه زوی شکیم دینه ولیدله، هغه یې راونیوله او بې‌عزته یې کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis34_verse_2.mp3', '', 1761754199, 1761754199),
(37306, 'Genesis 34:3', 'Genesis', 34, 3, 'د هغه زړه د یعقوب لور دینه یووړ او په هغې باندې مین شو. هغه هڅه کوله چې د هغې زړه لاسته راوړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis34_verse_3.mp3', '', 1761754199, 1761754199),
(37307, 'Genesis 34:4', 'Genesis', 34, 4, 'شکیم خپل پلار حمور ته وویل: «دا انجلۍ ماته وکړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis34_verse_4.mp3', '', 1761754199, 1761754199),
(37308, 'Genesis 34:5', 'Genesis', 34, 5, 'یعقوب خبر شو چې د هغه لور دینه بې‌عزته شوې ده. خو څرنګه چې د هغه زامن د خپلو پادو سره په صحرا کې وو، نو د هغوی تر راتللو پورې یې هېڅ ونه کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis34_verse_5.mp3', '', 1761754199, 1761754199),
(37309, 'Genesis 34:6', 'Genesis', 34, 6, 'د شکیم پلار حمور راغی چې د یعقوب سره خبرې وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis34_verse_6.mp3', '', 1761754199, 1761754199),
(37310, 'Genesis 34:7', 'Genesis', 34, 7, 'د یعقوب زامن له صحرا څخه راغلل او څنګه چې هغوی واورېدل چې څه پېښه شوې ده نو ډېر خواشیني او سخت په قهر شول، ځکه چې شکیم داسې کار کړی ؤ چې د کولو نه ؤ. هغه د یعقوب د لور په بې‌عزته کولو سره د اسراییلو د قوم سپکاوی کړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis34_verse_7.mp3', '', 1761754199, 1761754199);